const input = $json.body ?? $json;
const outcome = String(input.negotiation_outcome ?? input.outcome ?? '').toLowerCase();
const acceptedPrice = Number(input.accepted_price ?? input.counteroffer_amount ?? input.contract_price);
const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const identityOk = Boolean(dealId && leadId && propertyId);
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const hardBlock = blockers.length > 0;
const withinMao = Number.isFinite(acceptedPrice) && Number.isFinite(dynamicMao) && acceptedPrice <= dynamicMao;
let decision = 'needs_review';
let nextWorkflow = 'WF-126';
let status = 'blocked';
let humanReview = true;

if (!identityOk || hardBlock) {
  decision = 'needs_review';
  status = 'blocked';
} else if (['accepted','contract_ready','accept_counteroffer','accept_offer','seller_accepted'].includes(outcome)) {
  if (withinMao) {
    decision = 'contract_trigger';
    nextWorkflow = 'WF-201';
    status = 'ready_for_contract';
    humanReview = true;
  } else {
    decision = 'walk_away_or_reengage';
    nextWorkflow = 'WF-126';
    status = 'above_mao';
  }
} else if (['rejected','seller_rejected','declined'].includes(outcome)) {
  decision = 'rejection_reengagement';
  nextWorkflow = 'WF-261';
  status = 'reengagement_ready';
  humanReview = false;
} else if (['walk_away','walkaway'].includes(outcome)) {
  decision = 'walk_away_reengagement';
  nextWorkflow = 'WF-261';
  status = 'reengagement_ready';
  humanReview = false;
} else if (['revised_offer','counteroffer','counter'].includes(outcome)) {
  if (withinMao) {
    decision = 'revised_offer_follow_up';
    nextWorkflow = 'WF-255';
    status = 'offer_follow_up_ready';
  } else {
    decision = 'above_mao_reengagement';
    nextWorkflow = 'WF-261';
    status = 'reengagement_ready';
    humanReview = false;
  }
} else if (['timeout','no_response','silence'].includes(outcome)) {
  decision = 'reengagement';
  nextWorkflow = 'WF-261';
  status = 'reengagement_ready';
  humanReview = false;
} else {
  decision = 'needs_review';
  nextWorkflow = 'WF-126';
  status = 'needs_review';
}

return [{
  json: {
    ...input,
    workflow_id: 'WF-260',
    workflow_name: 'Negotiation Outcome → Contract Trigger / Rejection / Re-engagement Controller',
    decision,
    status,
    next_workflow: nextWorkflow,
    human_review_required: humanReview,
    accepted_price: Number.isFinite(acceptedPrice) ? acceptedPrice : null,
    dynamic_mao: Number.isFinite(dynamicMao) ? dynamicMao : null,
    mao_protected: Number.isFinite(acceptedPrice) && Number.isFinite(dynamicMao) ? acceptedPrice <= dynamicMao : false,
    identity_valid: identityOk,
    blockers,
    routing_reason: decision === 'contract_trigger'
      ? 'Seller accepted within dynamic MAO; route to contract package validation.'
      : decision.includes('reengagement')
        ? 'Negotiation ended without an executable agreement; route to seller re-engagement.'
        : decision === 'revised_offer_follow_up'
          ? 'Counter/revised offer remains within dynamic MAO; continue controlled offer follow-up.'
          : 'Outcome requires human review or is blocked by missing identity/evidence/MAO protection.',
    crm_activity: {
      activity_type: 'negotiation_outcome_routing',
      workflow_id: 'WF-260',
      decision,
      status,
      next_workflow: nextWorkflow,
      human_review_required: humanReview
    }
  }
}];
